-- Regenerate the aggregate approved_budgets rollup for FY2026 from the lines above.
insert into public.approved_budgets (
  fiscal_year, mda_id, personnel_amount, other_recurrent_amount,
  total_recurrent_amount, capital_amount, total_budget_amount, source_label
)
select
  2026 as fiscal_year,
  mda_id,
  coalesce(sum(approved_amount) filter (where budget_class = 'personnel'), 0),
  coalesce(sum(approved_amount) filter (where budget_class = 'overhead'), 0),
  coalesce(sum(approved_amount) filter (where budget_class in ('personnel', 'overhead')), 0),
  coalesce(sum(approved_amount) filter (where budget_class = 'capital'), 0),
  coalesce(sum(approved_amount), 0),
  'Kano State Health Sector 2026 Approved Budget (rolled up from line items)'
from public.approved_budget_lines
where fiscal_year = 2026
group by mda_id
on conflict (fiscal_year, mda_id) do update set
  personnel_amount = excluded.personnel_amount,
  other_recurrent_amount = excluded.other_recurrent_amount,
  total_recurrent_amount = excluded.total_recurrent_amount,
  capital_amount = excluded.capital_amount,
  total_budget_amount = excluded.total_budget_amount,
  source_label = excluded.source_label;

commit;
